def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)))
    n = min(sep, w - sep - 1)
    return [
        [2 if grid[r][c] != 0 and grid[r][sep + 1 + c] != 0 else 0 for c in range(n)]
        for r in range(h)
    ]
